--- Code.gs ---
/**
 * Signal engine for Harbourside Lettings.
 * Reads the "Signals" Gmail label and sends one daily digest of lease-law
 * and council-planning items. Everything else in the label is ignored.
 */

const CONFIG = {
  label: 'Signals',
  lookbackHours: 26,          // slight overlap with the daily run so nothing is missed
  maxThreads: 200,
  digestTo: null,             // null = send to the account that runs the script
  minScore: 3,
  seenIdLimit: 2000,          // how many processed message IDs to remember
  topicRules: {
    'Lease law': {
      keywords: [
        "renters' rights", 'renters rights act', 'section 21', 'section 8',
        'possession order', 'tenancy deposit', 'deposit protection',
        'housing act', 'right to rent', 'hmo licen', 'retaliatory eviction',
        'assured shorthold', 'periodic tenancy', 'minimum energy efficiency',
        'epc', 'gas safety', 'decent homes', 'landlord obligations'
      ]
    },
    'Council planning': {
      keywords: [
        'planning application', 'planning notice', 'planning committee',
        'change of use', 'article 4', 'local plan', 'consultation',
        'site notice', 'tree preservation order', 'conservation area',
        'planning permission', 'neighbour notification', 'hmo planning'
      ]
    }
  },
  // Sender domains that get a score boost, e.g. government and your council.
  trustedSenders: ['gov.uk', 'legislation.gov.uk'],
  // Phrases that mark a newsletter as noise, whatever the topic.
  noisePhrases: ['flash sale', '% off', 'webinar replay', 'sponsored by']
};

/** Compiled keyword regexes, built once per run. */
function buildMatchers_() {
  const matchers = {};
  Object.keys(CONFIG.topicRules).forEach(topic => {
    matchers[topic] = CONFIG.topicRules[topic].keywords.map(kw => ({
      kw,
      re: new RegExp('\\b' + kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i')
    }));
  });
  return matchers;
}

/** Scores one message. Returns null if it is not a signal. */
function scoreMessage_(msg, threadId, matchers) {
  const subject = msg.getSubject() || '';
  const body = msg.getPlainBody() || '';
  const from = msg.getFrom() || '';

  if (CONFIG.noisePhrases.some(p => body.toLowerCase().includes(p))) return null;

  let best = null;
  Object.keys(matchers).forEach(topic => {
    let hits = 0;
    matchers[topic].forEach(({ re }) => {
      if (re.test(subject)) hits += 2;        // subject match counts double
      else if (re.test(body)) hits += 1;
    });
    if (hits > 0 && (!best || hits > best.score)) best = { topic, score: hits };
  });
  if (!best) return null;

  const fromLower = from.toLowerCase();
  if (CONFIG.trustedSenders.some(d => fromLower.includes(d))) best.score += 2;
  if (best.score < CONFIG.minScore) return null;

  return {
    topic: best.topic,
    score: best.score,
    subject,
    from,
    date: msg.getDate(),
    snippet: body.replace(/\s+/g, ' ').trim().slice(0, 220),
    link: 'https://mail.google.com/mail/u/0/#all/' + threadId
  };
}

/** Finds new Signals threads and returns scored items plus IDs to remember. */
function collect_() {
  const props = PropertiesService.getScriptProperties();
  const seen = new Set(JSON.parse(props.getProperty('seenIds') || '[]'));
  const since = Math.floor((Date.now() - CONFIG.lookbackHours * 3600 * 1000) / 1000);
  const threads = GmailApp.search('label:"' + CONFIG.label + '" after:' + since, 0, CONFIG.maxThreads);
  const matchers = buildMatchers_();

  const items = [];
  const newIds = [];
  threads.forEach(thread => {
    const msg = thread.getMessages().pop();   // latest message in the thread
    const id = msg.getId();
    if (seen.has(id)) return;
    newIds.push(id);
    const item = scoreMessage_(msg, thread.getId(), matchers);
    if (item) items.push(item);
  });

  items.sort((a, b) => b.score - a.score || b.date - a.date);
  return { items, newIds, seen };
}

function escapeHtml_(s) {
  return String(s).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[c]);
}

function renderDigest_(items, dateLabel) {
  const sections = Object.keys(CONFIG.topicRules).map(topic => {
    const rows = items.filter(i => i.topic === topic);
    if (!rows.length) return '';
    const cards = rows.map(i => `
      <div style="margin:0 0 16px;padding:12px 14px;border-left:3px solid #2f5d50;background:#f7f7f5">
        <div style="font-weight:600;margin-bottom:4px">
          <a href="${escapeHtml_(i.link)}" style="color:#1d3b33;text-decoration:none">${escapeHtml_(i.subject)}</a>
        </div>
        <div style="font-size:12px;color:#666;margin-bottom:6px">
          ${escapeHtml_(i.from)} · ${escapeHtml_(i.date.toDateString())} · score ${i.score}
        </div>
        <div style="font-size:14px;color:#333">${escapeHtml_(i.snippet)}…</div>
      </div>`).join('');
    return `<h2 style="font-size:16px;margin:24px 0 12px;color:#1d3b33">${escapeHtml_(topic)} (${rows.length})</h2>${cards}`;
  }).join('');

  return `<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;color:#222">
    <h1 style="font-size:20px;margin:0">Signals digest</h1>
    <div style="font-size:13px;color:#666">${escapeHtml_(dateLabel)} · ${items.length} item(s)</div>
    ${sections}
  </div>`;
}

function plainDigest_(items, dateLabel) {
  const lines = ['Signals digest, ' + dateLabel + ' (' + items.length + ' items)', ''];
  Object.keys(CONFIG.topicRules).forEach(topic => {
    const rows = items.filter(i => i.topic === topic);
    if (!rows.length) return;
    lines.push(topic.toUpperCase() + ' (' + rows.length + ')');
    rows.forEach(i => lines.push('- ' + i.subject + ' (' + i.from + ')\n  ' + i.link));
    lines.push('');
  });
  return lines.join('\n');
}

/** Scheduled run: builds the digest and sends it. Remembers IDs only after a successful send. */
function sendDigest() {
  const { items, newIds, seen } = collect_();
  const dateLabel = new Date().toDateString();

  if (items.length > 0) {
    const to = CONFIG.digestTo || Session.getActiveUser().getEmail();
    MailApp.sendEmail({
      to,
      subject: 'Signals digest: ' + items.length + ' item(s), ' + dateLabel,
      body: plainDigest_(items, dateLabel),
      htmlBody: renderDigest_(items, dateLabel)
    });
  }

  newIds.forEach(id => seen.add(id));
  const trimmed = Array.from(seen).slice(-CONFIG.seenIdLimit);
  PropertiesService.getScriptProperties().setProperty('seenIds', JSON.stringify(trimmed));
  console.log('Digest run: ' + items.length + ' signal(s) from ' + newIds.length + ' new message(s).');
}

/** Dry run: logs what the digest would contain. Sends nothing and does not mark messages seen. */
function previewDigest() {
  const { items, newIds } = collect_();
  const dateLabel = new Date().toDateString();
  console.log(plainDigest_(items, dateLabel));
  console.log(items.length + ' signal(s) from ' + newIds.length + ' new message(s).');
}

/** Run once. Replaces any existing digest trigger with a daily one at 07:00 London time. */
function installDailyTrigger() {
  ScriptApp.getProjectTriggers().forEach(t => {
    if (t.getHandlerFunction() === 'sendDigest') ScriptApp.deleteTrigger(t);
  });
  ScriptApp.newTrigger('sendDigest').timeBased().everyDays(1).atHour(7).create();
}

--- README.md ---
# Signals digest: setup walkthrough

The script reads your Gmail label `Signals`, keeps only lease-law and council-planning items, and emails you one digest each morning at 07:00 (London time).

## 1. Create the project

1. Go to https://script.google.com while signed in as account-holder@example.com.
2. Click **New project**, name it "Signals digest".
3. Replace the contents of `Code.gs` with `signals/Code.gs`.
4. In **Project Settings** (gear icon), tick **Show "appsscript.json" manifest file in editor**. Then open `appsscript.json` and paste in `signals/appsscript.json`.

## 2. Check the config

At the top of `Code.gs`, `CONFIG` holds everything you are likely to tune:

| Setting | What it does |
|---|---|
| `label` | Must match your Gmail label name exactly. For a nested label, use `Parent/Child`. |
| `lookbackHours` | 26 gives a small overlap with the daily run. Duplicates are blocked by the seen-ID store, so overlap is safe. |
| `minScore` | Raise to 4 or 5 if too much noise gets through. Lower to 2 if you miss things. |
| `topicRules` | The keyword lists for each topic. Subject matches count double; body matches count once. |
| `trustedSenders` | Domains that get +2. Add your council's planning email domain here. |
| `noisePhrases` | Any message containing these is dropped entirely. |

The keyword lists are a starting point. Check them against current legislation and terms before you rely on them, and check which council domains send you planning notices.

## 3. Test it before scheduling

1. In the editor, choose `previewDigest` from the function dropdown and click **Run**.
2. Approve the permissions prompt (Gmail read, send email, and the trigger). The first run asks for these.
3. Open **Execution log**. You should see the digest as plain text, with a count of signals from new messages. Nothing is sent, and nothing is marked seen.
4. Tune `CONFIG` until the preview looks right, then repeat.

## 4. Schedule it

1. Choose `installDailyTrigger` and click **Run** once.
2. Check **Triggers** (clock icon). You should see `sendDigest`, daily, 7am to 8am.

To run the digest now, choose `sendDigest` and click **Run**. This will send an email if there are signals.

## How it works

1. **Fetch.** `GmailApp.search` pulls threads with the Signals label from the last 26 hours.
2. **Dedupe.** Message IDs go into script properties. Anything already seen is skipped, even when the lookback window overlaps.
3. **Score.** Each message is checked against the keyword lists. A keyword in the subject scores 2, in the body 1. A trusted sender adds 2. Messages with a noise phrase are dropped. Messages below `minScore` are dropped.
4. **Digest.** Items are grouped by topic and sorted by score. The email has an HTML version and a plain-text fallback. Each item links to its thread.
5. **Remember.** Seen IDs are saved only after the email sends. If sending fails, the items come back tomorrow instead of disappearing.

## Notes

- The digest is only sent when there is at least one signal. Quiet days produce no email.
- The script only reads Gmail and sends to you. It does not change labels, archive, or delete anything.
- Apps Script quotas allow the 200-thread cap and the daily trigger comfortably for forty messages a day.
- I have not run this against your live label. The `previewDigest` step is how you check it against real mail.

