--- Code.gs ---
/**
 * Northgate Cycles - service reminder letter factory.
 *
 * Bind this script to the customer Google Sheet (Extensions > Apps Script).
 * For each row that has no doc_url yet, it copies the letter template,
 * fills {{first_name}}, {{bike}} and {{due_date}}, moves the copy into the
 * output folder and writes the new doc's URL back to the row. Rows that
 * already have a doc_url are skipped, so re-running is safe.
 */

const CONFIG = {
  TEMPLATE_ID: 'PASTE_TEMPLATE_DOC_ID',
  OUTPUT_FOLDER_ID: 'PASTE_OUTPUT_FOLDER_ID',
  SHEET_NAME: 'Customers',          // tab name holding the 180 rows
  STATUS_HEADER: 'doc_url',         // written by the script; empty = not yet generated
  DATE_FORMAT: 'd MMMM yyyy',       // e.g. 14 March 2027
};

/** Menu entry so the team can run it from the sheet without opening the editor. */
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Service reminders')
    .addItem('Generate letters for new rows', 'generateServiceReminders')
    .addToUi();
}

function generateServiceReminders() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(CONFIG.SHEET_NAME);
  const values = sheet.getDataRange().getValues();
  const headers = values[0];
  const col = {};
  headers.forEach((h, i) => (col[String(h).trim()] = i));

  const required = ['first_name', 'bike', 'due_date', CONFIG.STATUS_HEADER];
  const missing = required.filter(h => !(h in col));
  if (missing.length) {
    throw new Error('Sheet is missing columns: ' + missing.join(', '));
  }

  const template = DriveApp.getFileById(CONFIG.TEMPLATE_ID);
  const folder = DriveApp.getFolderById(CONFIG.OUTPUT_FOLDER_ID);
  const tz = Session.getScriptTimeZone();

  let created = 0;
  let failed = 0;

  for (let r = 1; r < values.length; r++) {
    const row = values[r];
    if (row[col[CONFIG.STATUS_HEADER]]) continue;          // already generated
    if (!row[col['first_name']]) continue;                 // blank row

    try {
      const name = String(row[col['first_name']]).trim();
      const bike = String(row[col['bike']]).trim();
      const due = row[col['due_date']];
      const dueText = due instanceof Date
        ? Utilities.formatDate(due, tz, CONFIG.DATE_FORMAT)
        : String(due).trim();

      const copy = template.makeCopy('Service reminder - ' + name + ' (' + bike + ')', folder);
      const doc = DocumentApp.openById(copy.getId());
      const body = doc.getBody();
      body.replaceText(escapeRegex('{{first_name}}'), name);
      body.replaceText(escapeRegex('{{bike}}'), bike);
      body.replaceText(escapeRegex('{{due_date}}'), dueText);
      doc.saveAndClose();

      sheet.getRange(r + 1, col[CONFIG.STATUS_HEADER] + 1).setValue(copy.getUrl());
      created++;
    } catch (err) {
      failed++;
      sheet.getRange(r + 1, col[CONFIG.STATUS_HEADER] + 1).setValue('ERROR: ' + err.message);
    }
  }

  SpreadsheetApp.getUi().alert(
    'Service reminders: ' + created + ' created, ' + failed + ' failed.' +
    (failed ? '\nSee the doc_url column for the error on each row.' : '')
  );
}

function escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

